namespace stellar::v0_1 {
namespace {
struct Signature { std::string name; std::vector<std::string> parameters; std::string result; Span span{}; };
struct Import { std::string provider, symbol; Span span{}; };
struct Module { std::string id,path,source,body,source_hash,typed_hash; std::vector<Import> imports; std::vector<std::string> exports,dependencies; std::map<std::string,Signature> functions; };
struct Relic { std::string name,version,abi,hash; std::vector<std::string> effects,imports; std::map<std::string,Signature> exports; };
struct ManifestView { std::string entry,target,profile,version,integrity; std::vector<std::string> modules,relics,capabilities; };

std::string read_all(const std::filesystem::path&p){std::ifstream in(p,std::ios::binary);if(!in)throw std::runtime_error("read");return{std::istreambuf_iterator<char>(in),{}};}
std::string string_field(const std::string&json,const std::string&key){std::regex pattern("\\\""+key+"\\\"\\s*:\\s*\\\"([^\\\"]*)\\\"");std::smatch match;if(!std::regex_search(json,match,pattern))throw std::runtime_error("field");return match[1].str();}
std::vector<std::string> string_array_body(const std::string&body){std::vector<std::string>out;std::regex item("\\\"([^\\\"]*)\\\"");for(std::sregex_iterator i(body.begin(),body.end(),item),end;i!=end;++i)out.push_back((*i)[1].str());return out;}
std::vector<std::string> string_array(const std::string&json,const std::string&key){std::regex pattern("\\\""+key+"\\\"\\s*:\\s*\\[([^\\]]*)\\]");std::smatch match;if(!std::regex_search(json,match,pattern))throw std::runtime_error("array");return string_array_body(match[1].str());}
std::string hex_name(const std::string&value){std::ostringstream o;o<<std::hex<<std::setfill('0');for(unsigned char c:value)o<<std::setw(2)<<static_cast<unsigned int>(c);return o.str();}
std::string signature_text(const Signature&s){std::string out=s.name+"(";for(std::size_t i=0;i<s.parameters.size();++i){if(i)out+=',';out+=s.parameters[i];}return out+")->Result("+s.result+")";}
std::string mangle(const std::string&module,const Signature&s){const auto hash=sha256_text(signature_text(s));return"stellar_v01_m"+hex_name(module)+"_s"+hex_name(s.name)+"_h"+hash.substr(7,16);}
bool confined(const std::filesystem::path&root,const std::string&relative,std::filesystem::path&resolved){std::filesystem::path r(relative);if(r.empty()||r.is_absolute())return false;for(const auto&part:r)if(part=="..")return false;std::error_code ec;resolved=std::filesystem::weakly_canonical(root/r,ec);if(ec)return false;auto base=std::filesystem::weakly_canonical(root,ec);if(ec)return false;auto b=base.native(),x=resolved.native();std::transform(b.begin(),b.end(),b.begin(),::towlower);std::transform(x.begin(),x.end(),x.begin(),::towlower);return x.size()>b.size()&&x.compare(0,b.size(),b)==0&&(x[b.size()]=='\\'||x[b.size()]=='/');}
std::string json_string_array(std::vector<std::string>values){std::sort(values.begin(),values.end());std::ostringstream o;o<<'[';for(std::size_t i=0;i<values.size();++i){if(i)o<<',';o<<'"'<<json_escape(values[i])<<'"';}return o.str()+']';}
std::string ordered_json_string_array(const std::vector<std::string>&values){std::ostringstream o;o<<'[';for(std::size_t i=0;i<values.size();++i){if(i)o<<',';o<<'"'<<json_escape(values[i])<<'"';}return o.str()+']';}
std::vector<std::string> top_level_keys(const std::string&json){std::vector<std::string>keys;std::size_t depth=0;for(std::size_t i=0;i<json.size();){if(json[i]=='{'){++depth;++i;continue;}if(json[i]=='}'){if(depth)--depth;++i;continue;}if(json[i]=='"'){std::string value;++i;while(i<json.size()&&json[i]!='"'){if(json[i]=='\\'&&i+1<json.size())++i;value+=json[i++];}if(i<json.size())++i;std::size_t look=i;while(look<json.size()&&std::isspace(static_cast<unsigned char>(json[look])))++look;if(depth==1&&look<json.size()&&json[look]==':')keys.push_back(value);continue;}++i;}return keys;}
bool compatible_version(const std::string&version){return std::regex_match(version,std::regex("0\\.1\\.[0-9]+"));}
bool abi_type(const std::string&type){if(type=="bool"||type=="i32"||type=="i64"||type=="u32"||type=="u64"||type=="f64")return true;return std::regex_match(type,std::regex("(array|slice)\\((bool|i32|i64|u32|u64|f64),([1-9][0-9]{0,4})\\)"));}

class ModuleParser {
 public: ModuleParser(const Source&source,Diagnostic&error):source_(source),error_(error){}
  bool parse(Module&module){if(!lex(source_.display_path,source_.text,tokens_,error_))return false;try{parse_directives(module);parse_signatures(module);return true;}catch(...){return false;}}
 private:
  const Source&source_;Diagnostic&error_;std::vector<Token>tokens_;std::size_t at_{};
  const Token&peek(std::size_t n=0)const{return tokens_.at(std::min(at_+n,tokens_.size()-1));}
  bool word(const char*v)const{return peek().kind==TokenKind::identifier&&peek().value==v;}
  [[noreturn]]void fail(std::string code,std::string message,Span span,std::string help){error_={std::move(code),"error",std::move(message),source_.display_path,span,std::move(help)};throw std::runtime_error("module");}
  Token take(){return tokens_.at(at_++);}
  Token expect(TokenKind kind,const char*message){if(peek().kind!=kind)fail("S4001",message,peek().span,"use canonical module/import/export directives");return take();}
  Token id(){if(peek().kind!=TokenKind::identifier)fail("S4001","expected module or symbol identifier",peek().span,"use an identifier");return take();}
  std::string type(){auto name=id().value;if(name=="array"||name=="slice"){expect(TokenKind::left_crescent,"expected '(' in ABI type");auto inner=type();expect(TokenKind::comma,"expected ',' in ABI type");auto count=expect(TokenKind::number,"expected bound in ABI type").value;expect(TokenKind::right_crescent,"expected ')' in ABI type");return name+"("+inner+","+count+")";}return name;}
  void parse_directives(Module&m){if(!word("module"))fail("S4001","module file must begin with a module directive",peek().span,"write module NAME ·");take();m.id=id().value;expect(TokenKind::dot,"expected '·' after module directive");while(word("import")||word("export")){if(word("import")){auto start=take().span.start;auto provider=id();expect(TokenKind::angular,"expected '/' between module and symbol");auto symbol=id();auto end=expect(TokenKind::dot,"expected '·' after import");m.imports.push_back({provider.value,symbol.value,{start,end.span.end}});}else{take();auto symbol=id();m.exports.push_back(symbol.value);expect(TokenKind::dot,"expected '·' after export");}}if(peek().kind==TokenKind::end)fail("S4001","module contains no declarations",peek().span,"declare at least one function");m.body=source_.text.substr(peek().span.start.offset);}
  void parse_signatures(Module&m){while(peek().kind!=TokenKind::end){if(word("struct")){std::size_t depth=0;do{auto t=take();if(t.kind==TokenKind::left_crescent)++depth;if(t.kind==TokenKind::right_crescent)--depth;if(t.kind==TokenKind::dot&&depth==0)break;}while(peek().kind!=TokenKind::end);continue;}if(!word("function"))fail("S4001","module body accepts struct/function declarations only",peek().span,"move directives to the module header");auto start=take().span.start;auto name=id();Signature s{name.value};expect(TokenKind::left_crescent,"expected '(' after function name");if(peek().kind!=TokenKind::right_crescent)for(;;){id();expect(TokenKind::angular,"expected '/' before parameter type");s.parameters.push_back(type());if(peek().kind!=TokenKind::comma)break;take();}expect(TokenKind::right_crescent,"expected ')' after parameters");expect(TokenKind::angular,"expected '/' before Result");auto result=id();if(result.value!="Result")fail("S4005","exported ABI must use Result",result.span,"declare Result ( Type )");expect(TokenKind::left_crescent,"expected '(' after Result");s.result=type();expect(TokenKind::right_crescent,"expected ')' after result type");auto open=expect(TokenKind::left_crescent,"expected function body");std::size_t depth=1;while(depth&&peek().kind!=TokenKind::end){auto t=take();if(t.kind==TokenKind::left_crescent)++depth;if(t.kind==TokenKind::right_crescent)--depth;}if(depth)fail("S4001","unclosed function body",open.span,"close the function body");auto end=expect(TokenKind::dot,"expected '·' after function");s.span={start,end.span.end};if(!m.functions.emplace(s.name,s).second)fail("S4002","duplicate function symbol in module",s.span,"use unique function names");}}
};

bool parse_manifest_view(const std::filesystem::path&path,ManifestView&view,PackageInspection&base,Diagnostic&error){if(!inspect_manifest(path,base,error))return false;try{view.entry=string_field(base.canonical_manifest,"entry");view.target=string_field(base.canonical_manifest,"target");view.profile=string_field(base.canonical_manifest,"profile");view.version=string_field(base.canonical_manifest,"version");view.modules=string_array(base.canonical_manifest,"modules");view.relics=string_array(base.canonical_manifest,"relics");view.capabilities=string_array(base.canonical_manifest,"capabilities");view.integrity=base.integrity;if(!compatible_version(view.version))throw std::runtime_error("version");if(!view.capabilities.empty()){error={"S4003","error","v0.1 native capabilities remain blocked pending authenticated contracts and OS isolation",std::filesystem::absolute(path).generic_string(),{},"remove capabilities; checksum integrity is not authorization"};return false;}return true;}catch(...){if(error.code.empty())error={"S4005","error","package version is not compatible with Stellar v0.1",std::filesystem::absolute(path).generic_string(),{},"use a 0.1.x package version"};return false;}}

bool parse_relic(const std::filesystem::path&path,const std::string&target,const std::string&profile,Relic&relic,Diagnostic&error){const auto display=std::filesystem::absolute(path).generic_string();try{const auto text=read_all(path);if(text.size()>65536)throw std::runtime_error("size");const std::set<std::string>allowed{"schema","name","version","target","profile","abi","exports","effects","imports"};auto keys=top_level_keys(text);if(keys.size()!=allowed.size()||std::set<std::string>(keys.begin(),keys.end())!=allowed)throw std::runtime_error("fields");if(string_field(text,"schema")!="stellar.relic-interface/v0.1"||string_field(text,"target")!=target||string_field(text,"profile")!=profile||string_field(text,"abi")!="stellar-win64-v0.1")throw std::runtime_error("compat");relic.name=string_field(text,"name");relic.version=string_field(text,"version");if(!compatible_version(relic.version))throw std::runtime_error("version");relic.abi=string_field(text,"abi");relic.effects=string_array(text,"effects");relic.imports=string_array(text,"imports");if(!relic.effects.empty()||!relic.imports.empty()){error={"S4003","error","Tranche 2 RELIC interfaces must be capability-free and import-free",display,{},"defer OS effects to the capability-gated standard-library tranche"};return false;}std::regex item("\\{\\s*\\\"name\\\"\\s*:\\s*\\\"([^\\\"]+)\\\"\\s*,\\s*\\\"parameters\\\"\\s*:\\s*\\[([^\\]]*)\\]\\s*,\\s*\\\"result\\\"\\s*:\\s*\\\"([^\\\"]+)\\\"\\s*\\}");for(std::sregex_iterator i(text.begin(),text.end(),item),end;i!=end;++i){Signature s;s.name=(*i)[1].str();s.parameters=string_array_body((*i)[2].str());s.result=(*i)[3].str();if(!abi_type(s.result)||std::any_of(s.parameters.begin(),s.parameters.end(),[](const std::string&t){return!abi_type(t);})||!relic.exports.emplace(s.name,s).second)throw std::runtime_error("signature");}if(relic.exports.empty())throw std::runtime_error("empty");relic.hash=sha256_text(text);return true;}catch(...){if(error.code.empty())error={"S4005","error","RELIC interface target/profile/version/ABI/schema is incompatible or malformed",display,{},"use a unique capability-free 0.1.x stellar.relic-interface/v0.1 for stellar-win64-v0.1"};return false;}}

std::string stub(const Signature&s){std::ostringstream o;o<<"function "<<s.name<<" ( ";for(std::size_t i=0;i<s.parameters.size();++i){if(i)o<<", ";o<<"arg"<<i<<" / "<<s.parameters[i];}o<<" ) / Result ( "<<s.result<<" ) ( return err ( 1 ) · ) ·\n";return o.str();}
}

bool analyze_package_graph(const std::filesystem::path&manifest_path,PackageGraphAnalysis&analysis,Diagnostic&error,bool native_lowering){
  PackageInspection base;ManifestView manifest;if(!parse_manifest_view(manifest_path,manifest,base,error))return false;const auto root=std::filesystem::absolute(manifest_path).parent_path();std::map<std::string,Module>modules;std::map<std::string,Relic>relics;std::map<std::string,std::string>path_to_module;
  for(const auto&path:manifest.modules){Source source;if(!load_source(root/path,source,error))return false;Module module;module.path=path;module.source=source.text;module.source_hash=sha256_text(source.text);ModuleParser parser(source,error);if(!parser.parse(module))return false;if(modules.contains(module.id)){error={"S4001","error","duplicate module identity '"+module.id+"'",source.display_path,{},"use a unique module identity"};error.secondary_spans.push_back({(root/modules.at(module.id).path).generic_string(),{},"first declaration of this module identity"});return false;}modules.emplace(module.id,module);path_to_module[path]=module.id;}
  for(const auto&path:manifest.relics){std::filesystem::path resolved;if(!confined(root,path,resolved)||!std::filesystem::is_regular_file(resolved)){error={"S5002","error","RELIC path escapes its package root or is unavailable",std::filesystem::absolute(manifest_path).generic_string(),{},"use a contained regular RELIC interface path"};return false;}Relic relic;if(!parse_relic(resolved,manifest.target,manifest.profile,relic,error))return false;if(modules.contains(relic.name)||!relics.emplace(relic.name,relic).second){error={"S4001","error","duplicate module or RELIC identity '"+relic.name+"'",resolved.generic_string(),{},"use unique dependency identities"};return false;}}
  std::map<std::string,std::pair<std::string,Signature>>symbols;
  for(auto&[id,module]:modules){std::set<std::string>exports;for(const auto&name:module.exports){if(!exports.insert(name).second){error={"S4002","error","duplicate export '"+name+"'",module.path,{},"export a symbol once"};return false;}auto fn=module.functions.find(name);if(fn==module.functions.end()){error={"S4002","error","exported symbol is not a declared function",module.path,{},"export a declared function"};return false;}if(!abi_type(fn->second.result)||std::any_of(fn->second.parameters.begin(),fn->second.parameters.end(),[](const std::string&t){return!abi_type(t);})){error={"S4005","error","exported function uses a non-linkable v0.1 ABI type",module.path,fn->second.span,"use fixed-width scalars or bounded scalar array/slice types"};return false;}symbols.emplace(id+"::"+name,std::make_pair(id,fn->second));}}
  for(const auto&[id,relic]:relics)for(const auto&[name,sig]:relic.exports)symbols.emplace(id+"::"+name,std::make_pair(id,sig));
  for(auto&[id,module]:modules){std::set<std::string>local_imports;for(const auto&import:module.imports){if(!local_imports.insert(import.symbol).second||module.functions.contains(import.symbol)){error={"S4002","error","imported symbol name conflicts in module '"+id+"'",module.path,import.span,"use a unique local imported symbol"};return false;}if(!modules.contains(import.provider)&&!relics.contains(import.provider)){error={"S4002","error","import provider is unavailable",module.path,import.span,"declare the module or RELIC dependency"};return false;}auto symbol=symbols.find(import.provider+"::"+import.symbol);if(symbol==symbols.end()){error={"S4002","error","imported symbol is not exported by provider",module.path,import.span,"import an exported symbol"};return false;}if(modules.contains(import.provider))module.dependencies.push_back(import.provider);}std::sort(module.dependencies.begin(),module.dependencies.end());module.dependencies.erase(std::unique(module.dependencies.begin(),module.dependencies.end()),module.dependencies.end());}
  std::map<std::string,std::size_t>remaining;std::map<std::string,std::vector<std::string>>consumers;for(const auto&[id,module]:modules){remaining[id]=module.dependencies.size();for(const auto&dep:module.dependencies)consumers[dep].push_back(id);}std::set<std::string>ready;for(const auto&[id,count]:remaining)if(count==0)ready.insert(id);std::vector<std::string>order;while(!ready.empty()){auto id=*ready.begin();ready.erase(ready.begin());order.push_back(id);for(const auto&consumer:consumers[id])if(--remaining[consumer]==0)ready.insert(consumer);}if(order.size()!=modules.size()){error={"S4004","error","module dependency graph contains a cycle",std::filesystem::absolute(manifest_path).generic_string(),{},"use an acyclic package-root module graph"};return false;}
  for(auto&[id,module]:modules){std::string combined=module.body;std::map<std::string,std::string> external_symbols;for(const auto&import:module.imports){const auto& signature=symbols.at(import.provider+"::"+import.symbol).second;combined+='\n'+stub(signature);external_symbols[import.symbol]=mangle(import.provider,signature);}Source typed{root/module.path,(root/module.path).generic_string(),combined};TypedAnalysis typed_analysis;if(!analyze_typed_source(typed,typed_analysis,error))return false;module.typed_hash=sha256_text(typed_analysis.json);if(native_lowering){NativeModuleLowering lowering;std::set<std::string> exported(module.exports.begin(),module.exports.end());if(!lower_typed_native_module(typed,id,external_symbols,exported,lowering,error))return false;PackageGraphAnalysis::NativeModule native{id,"objects/"+hex_name(id)+".obj",std::move(lowering.assembly),std::move(lowering.trace_json),std::move(lowering.defined_symbols),std::move(lowering.undefined_symbols)};analysis.native_modules.push_back(std::move(native));}}
  std::ostringstream graph;graph<<'{';bool first=true;for(const auto&[id,module]:modules){if(!first)graph<<',';first=false;graph<<'"'<<json_escape(id)<<"\":"<<json_string_array(module.dependencies);}graph<<'}';const auto graph_hash=sha256_text(graph.str());std::ostringstream symbol_table;symbol_table<<'{';first=true;for(const auto&[qualified,item]:symbols){if(!first)symbol_table<<',';first=false;symbol_table<<'"'<<json_escape(qualified)<<"\":{\"signature\":\""<<json_escape(signature_text(item.second))<<"\",\"mangled\":\""<<mangle(item.first,item.second)<<"\"}";}symbol_table<<'}';const auto symbol_hash=sha256_text(symbol_table.str());
  std::ostringstream evidence_hashes,source_hashes,relic_hashes;evidence_hashes<<'{';source_hashes<<'{';first=true;for(const auto&[id,module]:modules){if(!first){evidence_hashes<<',';source_hashes<<',';}first=false;evidence_hashes<<'"'<<json_escape(id)<<"\":\""<<module.typed_hash<<'"';source_hashes<<'"'<<json_escape(id)<<"\":\""<<module.source_hash<<'"';}evidence_hashes<<'}';source_hashes<<'}';relic_hashes<<'{';first=true;for(const auto&[id,relic]:relics){if(!first)relic_hashes<<',';first=false;relic_hashes<<'"'<<json_escape(id)<<"\":\""<<relic.hash<<'"';}relic_hashes<<'}';std::ostringstream lock_core;lock_core<<"{\"dependencyGraphHash\":\""<<graph_hash<<"\",\"moduleEvidenceHashes\":"<<evidence_hashes.str()<<",\"moduleSourceHashes\":"<<source_hashes.str()<<",\"packageIntegrity\":\""<<manifest.integrity<<"\",\"relicHashes\":"<<relic_hashes.str()<<",\"schema\":\"stellar.dependency-lock/v0.1\",\"symbolTableHash\":\""<<symbol_hash<<"\"}";const auto lock_integrity=sha256_text(lock_core.str());analysis.dependency_lock="{\"dependencyGraphHash\":\""+graph_hash+"\",\"integrity\":\""+lock_integrity+"\",\"moduleEvidenceHashes\":"+evidence_hashes.str()+",\"moduleSourceHashes\":"+source_hashes.str()+",\"packageIntegrity\":\""+manifest.integrity+"\",\"relicHashes\":"+relic_hashes.str()+",\"schema\":\"stellar.dependency-lock/v0.1\",\"symbolTableHash\":\""+symbol_hash+"\"}";
  const auto effects_hash=sha256_text("{\"imports\":[],\"required\":[]}");std::map<std::string,std::string>interface_hashes,plan_hashes;for(const auto&[id,module]:modules){std::vector<std::string>exported,imported;for(const auto&name:module.exports)exported.push_back(id+"::"+signature_text(module.functions.at(name)));for(const auto&item:module.imports)imported.push_back(item.provider+"::"+signature_text(symbols.at(item.provider+"::"+item.symbol).second));interface_hashes[id]=sha256_text("{\"exports\":"+json_string_array(exported)+",\"imports\":"+json_string_array(imported)+"}");plan_hashes[id]=sha256_text(module.source_hash+"|"+module.typed_hash+"|"+interface_hashes[id]+"|"+graph_hash+"|"+symbol_hash+"|"+effects_hash+"|windows-x86_64-msvc|COFF-x64");}
  std::ostringstream out;out<<"{\"profile\":\"stellar-package-v0.1\",\"executionEnabled\":false,\"homeostasis\":\"NOT_EVALUATED\",\"dependencyGraphHash\":\""<<graph_hash<<"\",\"symbolTableHash\":\""<<symbol_hash<<"\",\"topologicalOrder\":"<<ordered_json_string_array(order)<<",\"modules\":{";first=true;for(const auto&[id,module]:modules){if(!first)out<<',';first=false;out<<'"'<<json_escape(id)<<"\":{\"path\":\""<<json_escape(module.path)<<"\",\"dependencies\":"<<json_string_array(module.dependencies)<<",\"sourceHash\":\""<<module.source_hash<<"\",\"typedEvidenceHash\":\""<<module.typed_hash<<"\",\"interfaceHash\":\""<<interface_hashes[id]<<"\"}";}out<<"},\"symbols\":"<<symbol_table.str()<<",\"relics\":{";first=true;for(const auto&[id,relic]:relics){if(!first)out<<',';first=false;out<<'"'<<json_escape(id)<<"\":{\"version\":\""<<json_escape(relic.version)<<"\",\"abi\":\""<<json_escape(relic.abi)<<"\",\"contentHash\":\""<<relic.hash<<"\",\"effects\":[]}";}out<<"},\"coffPlan\":[";first=true;for(const auto&id:order){const auto&module=modules.at(id);if(!first)out<<',';first=false;out<<"{\"module\":\""<<json_escape(id)<<"\",\"target\":\"windows-x86_64-msvc\",\"format\":\"COFF-x64\",\"abi\":\"stellar-win64-v0.1\",\"objectName\":\"objects/"<<hex_name(id)<<".obj\",\"sourceHash\":\""<<module.source_hash<<"\",\"typedEvidenceHash\":\""<<module.typed_hash<<"\",\"interfaceHash\":\""<<interface_hashes[id]<<"\",\"dependencyGraphHash\":\""<<graph_hash<<"\",\"symbolTableHash\":\""<<symbol_hash<<"\",\"effectsHash\":\""<<effects_hash<<"\",\"planHash\":\""<<plan_hashes[id]<<"\",\"objectHash\":null,\"objectEmitted\":false,\"executableLinked\":false}";}out<<"],\"effects\":{\"required\":[],\"imports\":[],\"hash\":\""<<effects_hash<<"\"},\"securityGate\":\"Custodian/Steward capability contract plus OS isolation required before arbitrary execution\"}";analysis.json=out.str();
  if(native_lowering){std::ostringstream native;native<<"{\"schema\":\"stellar.native-build-plan/v0.1\",\"target\":\""<<json_escape(manifest.target)<<"\",\"profile\":\""<<json_escape(manifest.profile)<<"\",\"abi\":\"stellar-win64-v0.1\",\"packageIntegrity\":\""<<manifest.integrity<<"\",\"dependencyLockIntegrity\":\""<<lock_integrity<<"\",\"symbolTableHash\":\""<<symbol_hash<<"\",\"effectsHash\":\""<<effects_hash<<"\",\"relics\":"<<relic_hashes.str()<<",\"modules\":[";first=true;for(const auto&id:order){auto emitted=std::find_if(analysis.native_modules.begin(),analysis.native_modules.end(),[&](const auto&m){return m.id==id;});if(emitted==analysis.native_modules.end())throw std::runtime_error("native plan");if(!first)native<<',';first=false;native<<"{\"module\":\""<<json_escape(id)<<"\",\"objectName\":\""<<emitted->object_name<<"\",\"assemblyName\":\"assembly/"<<hex_name(id)<<".asm\",\"assemblyHash\":\""<<sha256_text(emitted->assembly)<<"\",\"traceHash\":\""<<sha256_text(emitted->trace_json)<<"\",\"definedSymbols\":"<<json_string_array(emitted->defined_symbols)<<",\"undefinedSymbols\":"<<json_string_array(emitted->undefined_symbols)<<"}";}native<<"],\"effects\":[],\"imports\":[],\"executionEnabled\":false}";analysis.native_plan=native.str();}return true;
}

bool write_dependency_lock(const std::filesystem::path&manifest,const PackageGraphAnalysis&analysis,Diagnostic&error){try{std::ofstream out(manifest.parent_path()/"stellar.dependency.lock.json",std::ios::binary|std::ios::trunc);if(!out)throw std::runtime_error("write");out<<analysis.dependency_lock<<'\n';return true;}catch(...){error={"S5004","error","dependency lock could not be written",std::filesystem::absolute(manifest).generic_string(),{},"ensure the package directory is writable"};return false;}}
bool verify_dependency_lock(const std::filesystem::path&manifest,const PackageGraphAnalysis&analysis,Diagnostic&error){try{auto actual=read_all(manifest.parent_path()/"stellar.dependency.lock.json");while(!actual.empty()&&(actual.back()=='\n'||actual.back()=='\r'))actual.pop_back();if(actual==analysis.dependency_lock)return true;}catch(...){}error={"S5003","error","package dependency evidence does not match stellar.dependency.lock.json",std::filesystem::absolute(manifest).generic_string(),{},"restore reviewed bytes or issue a new reviewed lock; checksum integrity is not authorization"};return false;}
bool write_native_package_plan(const std::filesystem::path&manifest,const std::filesystem::path&output,const PackageGraphAnalysis&analysis,Diagnostic&error){try{const auto absolute=std::filesystem::absolute(output);std::filesystem::create_directories(absolute/"assembly");for(const auto&module:analysis.native_modules){const auto name=std::filesystem::path(module.object_name).stem().string();std::ofstream assembly(absolute/"assembly"/(name+".asm"),std::ios::binary|std::ios::trunc);if(!assembly)throw std::runtime_error("assembly");assembly<<module.assembly;std::ofstream trace(absolute/"assembly"/(name+".trace.json"),std::ios::binary|std::ios::trunc);if(!trace)throw std::runtime_error("trace");trace<<module.trace_json<<'\n';}std::ofstream plan(absolute/"native-plan.json",std::ios::binary|std::ios::trunc);if(!plan)throw std::runtime_error("plan");plan<<analysis.native_plan<<'\n';std::ofstream lock(absolute/"stellar.dependency.lock.json",std::ios::binary|std::ios::trunc);if(!lock)throw std::runtime_error("lock");lock<<analysis.dependency_lock<<'\n';return true;}catch(...){error={"S6003","error","native package plan could not be written",std::filesystem::absolute(manifest).generic_string(),{},"use a writable confined output directory"};return false;}}
}
